const email = Array.isArray($input.item.json) ? $input.item.json[0] : $input.item.json;

// Fonction pour extraire uniquement le premier message (pas l'historique)
function extractFirstMessage(text) {
  if (!text) return '';

  // Cherche les marqueurs courants de début d'historique
  const markers = [
    '--- original message ---',
    '--- end of original message ---',
    'On December',
    'On November',
    '> On ',
    '>>>',
    'Retrouvez notre centre d\'aide syndic en ligne'
  ];

  let firstMessageEnd = text.length;

  for (const marker of markers) {
    const index = text.indexOf(marker);
    if (index !== -1 && index < firstMessageEnd) {
      firstMessageEnd = index;
    }
  }

  // Retourne le texte jusqu'au premier marqueur trouvé et nettoie
  return text.substring(0, firstMessageEnd).trim();
}

const firstMessageText = extractFirstMessage(email.text);

return {
  json: {
    gmail_id: email.id,
    thread_id: email.threadId,
    message_id: email.messageId,
    date: email.date,
    received_at: new Date().toISOString(),
    from_email: email.from.value[0].address,
    from_name: email.from.value[0].name,
    to_emails: email.to.value.map(t => t.address),
    to_names: email.to.value.map(t => t.name),
    subject: email.subject,
    text_content: firstMessageText,
    reply_to: email.replyTo?.value?.[0]?.address || null,
    in_reply_to: email.inReplyTo || null,
    references: email.references || [],
    label_ids: email.labelIds || [],
    size_estimate: email.sizeEstimate
  }
};

